export class Pools {
  private readonly session = inject(Session);
  private readonly api = inject(PoolsApi);

  /** The sheet's people, to choose members from and to tell who is retired. */
  readonly people = input.required<PersonView[]>();
  /** The sheet's today (yyyy-mm-dd). */
  readonly today = input.required<string>();

  protected readonly pools = signal<PoolView[]>([]);
  protected readonly name = signal('');
  protected readonly error = signal<string | null>(null);
  /** The member (person:<id> or pool:<id>) and share chosen on each pool's row, by pool id. */
  protected readonly drafts = signal(new Map<number, { member: string; share: string }>());
  /** The error shown on each pool's row, by pool id. */
  protected readonly errors = signal(new Map<number, string>());
  /**
   * Each pool with its total share, a retired member's share counting as 0.00, and, when it is balanced
   * and it has a pot, each member's cut of the pot.
   */
  protected readonly lines = computed<PoolLine[]>(() => {
    const retired = new Set(this.people().filter((p) => retiredOn(p, this.today())).map((p) => p.id));
    const pools = this.pools();
    const parents = this.parents();
    const sheetPot = this.session.pot();
    const totals = new Map(
      pools.map((pool) => [pool.id, pool.members.reduce((sum, m) => sum + (isRetired(m, retired) ? 0 : cents(m.share)), 0)]),
    );
    // Each pool's cuts in cents, a pool's pot being the sheet's or its cut in the pool above; none when
    // the pool is unbalanced or has no pot.
    const memo = new Map<number, Map<string, bigint>>();
    const cutsOf = (pool: PoolView): Map<string, bigint> => {
      const known = memo.get(pool.id);
      if (known) return known;
      memo.set(pool.id, new Map());
      let pot: bigint | undefined;
      const parentId = parents.get(pool.id);
      const parent = parentId === undefined ? undefined : pools.find((p) => p.id === parentId);
      if (parent) pot = cutsOf(parent).get(`pool:${pool.id}`);
      else if (parentId === undefined && sheetPot !== '') pot = BigInt(cents(sheetPot));
      const found = totals.get(pool.id) === 10000 && pot !== undefined ? cuts(pool, pot, retired) : new Map<string, bigint>();
      memo.set(pool.id, found);
      return found;
    };
    return pools.map((pool) => {
      const total = totals.get(pool.id) ?? 0;
      const shown = new Map([...cutsOf(pool)].map(([id, c]) => [id, money(Number(c))]));
      return { pool, total: money(total), balanced: total === 10000, cuts: shown };
    });
  });
  /** The pool each member pool is in, by member pool id. */
  private readonly parents = computed(
    () => new Map(this.pools().flatMap((pool) => pool.members.filter((m) => m.poolId !== null).map((m) => [m.poolId!, pool.id]))),
  );
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;

  constructor() {
    // Every sheet load re-reads the sheet's pools from the store.
    effect(() => {
      const sheet = this.session.sheet();
      const loads = this.session.loads();
      untracked(() => {
        this.pools.set([]);
        this.error.set(null);
        this.drafts.set(new Map());
        this.errors.set(new Map());
        if (sheet) void this.reload(sheet, loads);
      });
    });
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement | HTMLSelectElement).value;
  }

  protected readonly key = key;

  protected draft(poolId: number, change: Partial<{ member: string; share: string }>): void {
    this.drafts.update((all) => {
      const next = new Map(all);
      next.set(poolId, { member: '', share: '', ...all.get(poolId), ...change });
      return next;
    });
    this.setError(poolId, null);
  }

  protected async add(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.error.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const name = this.name().trim();
    if (!name) {
      this.error.set('Type a name for the pool.');
      return;
    }
    if (this.pools().some((p) => p.name === name)) {
      this.error.set(`There is already a pool named ${name}.`);
      return;
    }
    this.busy = true;
    try {
      const saved = await this.api.add(sheet, name);
      this.pools.update((all) => [...all, saved]);
      this.name.set('');
    } catch {
      this.error.set(`The pool ${name} could not be added: the name may already be taken.`);
    } finally {
      this.busy = false;
    }
  }

  protected async addMember(event: Event, pool: PoolView): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.setError(pool.id, null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const draft = this.drafts().get(pool.id) ?? { member: '', share: '' };
    const [kind, raw] = draft.member.split(':');
    const id = Number(raw);
    let member: { personId: number } | { poolId: number };
    if (kind === 'pool' && this.pools().some((p) => p.id === id)) {
      const refused = this.refusePool(pool.id, id);
      if (refused) {
        this.setError(pool.id, refused);
        return;
      }
      member = { poolId: id };
    } else if (kind === 'person' && this.people().some((p) => p.id === id)) {
      if (pool.members.some((m) => m.personId === id)) {
        this.setError(pool.id, 'That person is already in the pool.');
        return;
      }
      member = { personId: id };
    } else {
      this.setError(pool.id, 'Choose a person or a pool to add to the pool.');
      return;
    }
    const share = draft.share.trim();
    if (!SHARE.test(share) || cents(share) <= 0 || cents(share) > 10000) {
      this.setError(pool.id, 'A share is more than 0.00 and at most 100.00, with two decimals.');
      return;
    }
    this.busy = true;
    try {
      const saved = await this.api.addMember(sheet, pool.id, member, share);
      this.pools.update((all) => all.map((p) => (p.id === saved.id ? saved : p)));
      this.drafts.update((all) => {
        const next = new Map(all);
        next.delete(pool.id);
        return next;
      });
    } catch {
      this.setError(pool.id, 'The member could not be added: they may already be in the pool, or the pool in another.');
    } finally {
      this.busy = false;
    }
  }

  /**
   * Why a pool may not be added to another: it would contain itself through a chain, it is a member of a
   * pool already, or the chain would be more than three deep; null when it may.
   */
  private refusePool(poolId: number, memberId: number): string | null {
    const parents = this.parents();
    for (let up: number | undefined = poolId; up !== undefined; up = parents.get(up)) {
      if (up === memberId) return 'A pool cannot contain itself.';
    }
    if (parents.has(memberId)) return 'That pool is already a member of a pool.';
    let depth = 1;
    for (let up = parents.get(poolId); up !== undefined; up = parents.get(up)) depth++;
    const height = (id: number): number =>
      1 + Math.max(0, ...[...parents].filter(([, parent]) => parent === id).map(([child]) => height(child)));
    if (depth + height(memberId) > MAX_DEPTH) return 'A chain of pools is at most three deep.';
    return null;
  }

  private setError(poolId: number, message: string | null): void {
    if (message === null && !this.errors().has(poolId)) return;
    this.errors.update((all) => {
      const next = new Map(all);
      if (message === null) next.delete(poolId);
      else next.set(poolId, message);
      return next;
    });
  }

  private async reload(sheet: string, loads: number): Promise<void> {
    const pools = await this.api.list(sheet);
    // A later load may have started while this one was in flight: only the latest is shown.
    if (this.session.sheet() === sheet && this.session.loads() === loads) this.pools.set(pools);
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** A pool's member: a person on the sheet or another pool (the other null), its name, and its share percent with two decimals. */
export interface PoolMemberView {
  personId: number | null;
  poolId: number | null;
  name: string;
  share: string;
}

/** A pool on the sheet: a name, once per sheet, and its members in the order they were added. */
export interface PoolView {
  id: number;
  name: string;
  members: PoolMemberView[];
}

// The sheet's pools, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class PoolsApi {
  private readonly http = inject(HttpClient);

  /** The sheet's pools in the order they were added. */
  list(sheet: string): Promise<PoolView[]> {
    return firstValueFrom(this.http.get<PoolView[]>(this.url(sheet)));
  }

  /** Add a pool; refused when its name, trimmed, is blank or already a pool's. */
  add(sheet: string, name: string): Promise<PoolView> {
    return firstValueFrom(this.http.post<PoolView>(this.url(sheet), { name }));
  }

  /**
   * Add a person, or another pool, to a pool with a share; refused when the person is in it already, the
   * share is bad, or the member pool is in a pool already, would contain itself, or would be too deep.
   */
  addMember(sheet: string, poolId: number, member: { personId: number } | { poolId: number }, share: string): Promise<PoolView> {
    return firstValueFrom(this.http.post<PoolView>(`${this.url(sheet)}/${poolId}/members`, { ...member, share }));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/pools`;
  }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The pools on a sheet: listed with their members, added, and given members. */
@Service
public class PoolService {

    private static final BigDecimal MAX_SHARE = new BigDecimal("100.00");

    /** How many pools deep a chain of pools may be, the pool that is a member of none counting as one. */
    private static final int MAX_DEPTH = 3;

    /** A pool with its members in the order they were added, each with the person's name. */
    public record PoolWithMembers(Pool pool, List<Member> members) {
    }

    /** A member with its name: the person's, or the member pool's. */
    public record Member(PoolMember member, String name) {
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            SheetService sheets, Audit audit) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's pools in the order they were added, with their members. */
    @Transactional(readOnly = true)
    public List<PoolWithMembers> list(String sheetId) {
        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, String> names = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Person::getName));
        Map<Long, String> poolNames = all.stream().collect(Collectors.toMap(Pool::getId, Pool::getName));
        Map<Long, List<Member>> byPool = members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())
                .stream().map(m -> new Member(m, m.getMemberPoolId() != null ? poolNames.get(m.getMemberPoolId())
                        : names.get(m.getPersonId())))
                .collect(Collectors.groupingBy(m -> m.member().getPoolId()));
        return all.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()))).toList();
    }

    /** Add a pool; refused when its name, trimmed, is blank or already a pool's on the sheet. */
    @Transactional
    public PoolWithMembers add(String sheetId, String user, String name) {
        String trimmed = name.strip();
        if (trimmed.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A pool needs a name.");
        }
        sheets.lock(sheetId);
        if (pools.existsBySheetIdAndName(sheetId, trimmed)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "There is already a pool by that name.");
        }
        Pool saved = pools.saveAndFlush(new Pool(sheetId, trimmed));
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + trimmed);
        return new PoolWithMembers(saved, List.of());
    }

    /**
     * Add a person on the sheet to a pool with a share percent; refused when the share is not more than
     * 0.00 and at most 100.00 with two decimals, or the person is already in the pool.
     */
    @Transactional
    public PoolWithMembers addMember(String sheetId, String user, long poolId, long personId, BigDecimal share) {
        if (share.scale() > 2 || share.signum() <= 0 || share.compareTo(MAX_SHARE) > 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A share is more than 0.00 and at most 100.00, with two decimals.");
        }
        sheets.lock(sheetId);
        Pool pool = pools.findBySheetIdAndId(sheetId, poolId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
        Person person = people.findById(personId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (members.existsByPoolIdAndPersonId(poolId, personId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool.");
        }
        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
        members.saveAndFlush(new PoolMember(poolId, personId, scaled));
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + person.getName() + " share=" + scaled.toPlainString());
        return list(sheetId).stream().filter(p -> p.pool().getId().equals(poolId)).findFirst().orElseThrow();
    }

    /**
     * Add another pool on the sheet to a pool with a share percent; refused when the share is bad, the pool
     * would contain itself through any chain, the member pool is already a member of a pool, or the chain of
     * pools would be more than three deep.
     */
    @Transactional
    public PoolWithMembers addPoolMember(String sheetId, String user, long poolId, long memberPoolId,
            BigDecimal share) {
        if (share.scale() > 2 || share.signum() <= 0 || share.compareTo(MAX_SHARE) > 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A share is more than 0.00 and at most 100.00, with two decimals.");
        }
        sheets.lock(sheetId);
        Pool pool = pools.findBySheetIdAndId(sheetId, poolId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
        Pool member = pools.findBySheetIdAndId(sheetId, memberPoolId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
        // Each member pool's parent, and each pool's member pools, across the sheet.
        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, Long> parents = new HashMap<>();
        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())) {
            if (m.getMemberPoolId() != null) parents.put(m.getMemberPoolId(), m.getPoolId());
        }
        for (Long up = pool.getId(); up != null; up = parents.get(up)) {
            if (up.equals(member.getId())) {
                throw new ResponseStatusException(HttpStatus.CONFLICT, "A pool cannot contain itself.");
            }
        }
        if (parents.containsKey(member.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already a member of a pool.");
        }
        if (depth(pool.getId(), parents) + height(member.getId(), parents) > MAX_DEPTH) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A chain of pools is at most three deep.");
        }
        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
        members.saveAndFlush(PoolMember.ofPool(poolId, memberPoolId, scaled));
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + member.getName() + " share=" + scaled.toPlainString());
        return list(sheetId).stream().filter(p -> p.pool().getId().equals(poolId)).findFirst().orElseThrow();
    }

    /** How deep a pool is in its chain: 1 for a pool that is a member of none. */
    private static int depth(Long poolId, Map<Long, Long> parents) {
        int depth = 1;
        for (Long up = parents.get(poolId); up != null; up = parents.get(up)) depth++;
        return depth;
    }

    /** How many pools deep the chain below a pool is, the pool itself counting as one. */
    private static int height(Long poolId, Map<Long, Long> parents) {
        int height = 1;
        for (Map.Entry<Long, Long> e : parents.entrySet()) {
            if (e.getValue().equals(poolId)) height = Math.max(height, 1 + height(e.getKey(), parents));
        }
        return height;
    }
}
